package app.aaps.plugins.aps.camapsfx

/**
 * The estimator cold-init template — the 8-submodel `newPatient` image the genuine binary starts each tick from
 * (bit-exact-validated; plant params are f2-determined Initialise DEFAULTS, weight-independent, so this one
 * template serves any body weight — the runtime weight is applied via Plant(weight)/vg per tick). Embedded as
 * data so the plugin needs no asset/Context. Format: `entry<i>_allf|allst|P <hex-float ...>`.
 */
object CamapsColdInit {
    private val cAllf = Array(8) { FloatArray(196) }
    private val cAllst = Array(8) { FloatArray(81) }
    private val cP = Array(8) { FloatArray(36) }

    init {
        fun bits(h: String) = Float.fromBits(java.lang.Long.parseLong(h, 16).toInt())
        for (line in TEMPLATE.split("\n")) {
            val t = line.trim().split(Regex("\\s+")); if (t[0].isEmpty()) continue
            val i = t[0].removePrefix("entry").takeWhile { it.isDigit() }.toInt()
            when {
                t[0].endsWith("_allf") -> for (k in 0 until 196) cAllf[i][k] = bits(t[k + 1])
                t[0].endsWith("_allst") -> for (k in 0 until 81) cAllst[i][k] = bits(t[k + 1])
                t[0].endsWith("_P") -> for (k in 0 until 36) cP[i][k] = bits(t[k + 1])
            }
        }
    }

    /** A fresh 8-submodel cold-init for the given body weight (plant weight/vg set per tick). */
    fun coldInit(weight: Float): Array<Submodel> = Array(8) { i ->
        val a = cAllf[i]; fun g(off: Int) = a[off / 4]
        val sm = Submodel(idx = i + 1, plant = Plant(weight, g(0x3c), g(0x8)), multWini = g(0x34), multWk31 = g(0x38), usRegressionOn = true)
        sm.f0c = g(0xc); sm.f10 = g(0x10); sm.tMaxIs = g(0x14); sm.tMaxIBase = g(0x18); sm.f28 = g(0x28); sm.f40 = g(0x40)
        sm.f1c = g(0x1c); sm.f20 = g(0x20); sm.f24 = g(0x24); sm.vg = weight; sm.stateLen = 69
        sm.bicBir = g(0x224); sm.birStep = g(0x220); sm.lastDt = g(0x21c); sm.last238 = g(0x238); sm.f228 = g(0x228)
        sm.plant.iRef = g(0x22c); sm.plant.f01 = g(0x230); sm.plant.egpHalf = g(0x234); sm.plant.tMaxIAbs = g(0x238); sm.plant.si = g(0x23c)
        sm.f240 = g(0x240); sm.f244 = g(0x244)
        for (off in 0x248..0x30c step 4) sm.setCoef(off, g(off))
        for (k in 0 until 81) sm.st[k] = cAllst[i][k]
        for (r in 0 until 6) for (c in 0 until 6) sm.P[r][c] = cP[i][r * 6 + c]
        sm
    }

